let LANG='ar';
function t(k,...a){let s=(I18N[LANG]&&I18N[LANG][k]);if(s==null)s=I18N.ar[k]??k;return s.replace(/\{(\d)\}/g,(_,i)=>a[i]??'')}
const L=()=>LOC[LANG];
function applyI18n(){document.documentElement.lang=LANG;document.documentElement.dir=LANG==='ar'?'rtl':'ltr';document.title=t('app');{const hb=document.getElementById('helpBtn');if(hb)hb.title=t('tour.again')}
  $$('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));$$('[data-i18n-ph]').forEach(e=>e.placeholder=t(e.dataset.i18nPh));
  $('#logo').textContent=t('app');$('#logo').dataset.t=t('app');}

