function kidName(c){const d=DEF_CAT[c.id];if(d&&(c.name===d.ar||c.name===d.en))return d[LANG];return c.name}
function catName(c){if(c&&c.parent){const p=S.settings.categories.find(x=>x.id===c.parent);if(p)return kidName(p)+' · '+kidName(c)}return kidName(c)}
